window.docContents[49].resolve({"/7___-Introduction-to-categories/7___2___-Functors/Composition-of-functors-and-identity-functor/#Chapter7___Discussion_after_Definition7___2___1":{"contents":"Note that functors can be composed in an obvious way. Also, any category has the identity functor.\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.2. Functors\tComposition of functors and identity functor","header":"Composition of functors and identity functor","id":"/7___-Introduction-to-categories/7___2___-Functors/Composition-of-functors-and-identity-functor/#Chapter7___Discussion_after_Definition7___2___1"},"/2___-Basic-notions-of-representation-theory/2___3___-Representations/1-dimensional-representations-are-automatically-irreducible/#Chapter2___Remark2___3___13":{"contents":"Remark 2.3.13. Note that a 1-dimensional representation of any algebra is automatically irreducible.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.3. Representations\t1-dimensional representations are automatically irreducible","header":"1-dimensional representations are automatically irreducible","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/1-dimensional-representations-are-automatically-irreducible/#Chapter2___Remark2___3___13"}});
